#include <iostream>
#include <string>

int main() {
    std::string original = "This is a test string for find function";
    std::string substring = "test";
    std::size_t position = original.find(substring);  // Starts search from position 0
    if (position != std::string::npos) {
        std::cout << "Substring found at position: " << position << std::endl;
    } else {
        std::cout << "Substring not found" << std::endl;
    }
    return 0;
}
